const LOGO_ICON = "data:image/png;base64,";
const LOGO_WORDMARK = "data:image/png;base64,";
function wordmark(big){
  if(big) return `<div style="display:inline-flex;align-items:center;justify-content:center;gap:10px;white-space:nowrap;margin:0 auto 6px"><img src="${LOGO_ICON}" alt="KoneKA" style="width:38px;height:38px;border-radius:50%;flex-shrink:0;box-shadow:0 4px 14px rgba(0,0,0,0.1)"><div style="font-size:28px;font-weight:800;letter-spacing:-0.03em;white-space:nowrap;line-height:1;display:inline-block;color:var(--text-1)">Kone<strong style="color:var(--red);font-weight:800;font-style:normal">KA</strong></div></div>`;
  return `<div style="display:inline-flex;align-items:center;gap:7px;white-space:nowrap;flex-shrink:0;line-height:1"><img src="${LOGO_ICON}" alt="KoneKA" style="width:22px;height:22px;border-radius:50%;flex-shrink:0;display:block"><div style="font-size:15px;font-weight:800;letter-spacing:-0.02em;white-space:nowrap;line-height:1;display:inline-block;color:var(--text-1)">Kone<strong style="color:var(--red);font-weight:800;font-style:normal">KA</strong></div></div>`;
}
function logoIcon(size){
  size = size || 26;
  return `<img src="${LOGO_ICON}" alt="KoneKA" style="width:${size}px;height:${size}px;border-radius:50%;display:block;flex-shrink:0">`;
}

